    out = [row[:] for row in grid]
    centers = []

    # Find 3x3 objects with a 2 at the center and 3s around it.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    for r, c in centers:
        # The object fires perpendicular to the 2-line it lies on.
        vertical_beam = sum(v == 2 for v in grid[r]) > sum(
            grid[rr][c] == 2 for rr in range(h)
        )

        if vertical_beam:
            points = [(rr, c) for rr in range(h) if rr != r]
        else:
            points = [(r, cc) for cc in range(w) if cc != c]

        for rr, cc in points:
            if grid[rr][cc] == 0:
                out[rr][cc] = 1
            elif grid[rr][cc] == 2:
                # At a crossed 2-line, illuminate a 3x3 flare,
                # leaving the central 2 intact.
                for ar in range(max(0, rr - 1), min(h, rr + 2)):
                    for ac in range(max(0, cc - 1), min(w, cc + 2)):
                        if (ar, ac) != (rr, cc) and grid[ar][ac] != 3:
                            out[ar][ac] = 1

    return out
